        flags.SetValue(data,RenderFlags.Visible|RenderFlags.CastShadows|RenderFlags.SkipInMainView);mark.Invoke(scene,new[]{data});Frame();Check(!((System.Collections.IEnumerable)typeof(VulkanScene).GetField("visible",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(scene)!).Cast<uint>().Contains(200u),"GPU visible-owner notifications honor SkipInMainView");flags.SetValue(data,RenderFlags.Visible|RenderFlags.CastShadows);mark.Invoke(scene,new[]{data});Frame();backend.Resize(96,96,0);Frame();backend.Resize(64,64,0);Frame();Check(Owned(),"resident ownership survives resize and both fenced slots");scene.Process(new MyRenderMessageSetInstanceBuffer{ID=200,InstanceBufferId=300,InstanceCount=1,InstanceData=new[]{new VRage.MyInstanceData(Matrix.Identity)},LocalAabb=new BoundingBox(new Vector3(-2),new Vector3(2))});Frame();Check(Owned()&&(bool)data.GetType().GetField("GpuOld")!.GetValue(data)!,"generic source admission owns OLD instance stream");scene.Process(new MyRenderMessageUpdateRenderInstanceBufferRange{ID=300,StartOffset=0,Trim=true,InstanceData=new[]{new VRage.MyInstanceData(Matrix.CreateTranslation(.5f,0,0))}});var changedSource=Frame();Check(Owned(),"instance source replacement preserves resident ownership");scene.GpuOpaqueOwnershipEnabled=false;Check(Frame().SequenceEqual(changedSource),"updated OLD source and appearance match canonical fallback image");scene.GpuOpaqueOwnershipEnabled=true;Check(Frame().SequenceEqual(changedSource)&&Owned(),"updated source reentry matches both frame slots");pose=MatrixD.CreateScale(1.1)*MatrixD.CreateRotationY(.12);root.SetMatrix(ref pose);var oldPose=Frame();scene.GpuOpaqueOwnershipEnabled=false;Check(Frame().SequenceEqual(oldPose),"OLD parent rotation and scale match fallback");scene.GpuOpaqueOwnershipEnabled=true;Check(Frame().SequenceEqual(oldPose)&&Frame().SequenceEqual(oldPose),"OLD retained defaults preserve current pose in both slots");scene.Process(new MyRenderMessageUpdateRenderEntity{ID=200,DiffuseColor=Color.Green});var oldAppearance=Frame();scene.GpuOpaqueOwnershipEnabled=false;Check(Frame().SequenceEqual(oldAppearance),"OLD appearance change refreshes retained defaults");scene.GpuOpaqueOwnershipEnabled=true;Check(Frame().SequenceEqual(oldAppearance)&&Frame().SequenceEqual(oldAppearance),"OLD appearance reentry matches both slots");pose=MatrixD.Identity;root.SetMatrix(ref pose);Frame();scene.Process(new MyRenderMessageCreateRenderEntity{ID=201,Model=Path.Combine(content,"Models/Cubes/Large/ArmorCenter.mwm"),DebugName="CPU native fallback",WorldMatrix=MatrixD.CreateTranslation(2,0,-5),Flags=RenderFlags.Visible|RenderFlags.CastShadows});
